//! Exact Windows help content, checked against the complete original C entry.
pub(super) const FORMAT: &std::ffi::CStr = c" @<config_file>|$<config_file>\t\t\t\t; read file for options. must be the only argument. other options are ignored.\n\n --debug=0|1|syslog|@<filename>\n --version\t\t\t\t\t\t; print version and exit\n --dry-run\t\t\t\t\t\t; verify parameters and exit with code 0 if successful\n --comment=any_text\n --intercept=0|1\t\t\t\t\t; enable interception. if disabled - run lua-init and exit\n --daemon\t\t\t\t\t\t; daemonize\n --chdir[=path]\t\t\t\t\t\t; change current directory. if no path specified use EXEDIR\n --pidfile=<filename>\t\t\t\t\t; write pid to file\n --ctrack-timeouts=S:E:F[:U]\t\t\t\t; internal conntrack timeouts for TCP SYN, ESTABLISHED, FIN stages, UDP timeout. default %u:%u:%u:%u\n --ctrack-disable=[0|1]\t\t\t\t\t; 1 or no argument disables conntrack\n --payload-disable=[type[,type]]\t\t\t; do not discover these payload types. for available payload types see '--payload'. disable all if no argument.\n --server=[0|1]\t\t\t\t\t\t; change multiple aspects of src/dst ip/port handling for incoming connections\n --ipcache-lifetime=<int>\t\t\t\t; time in seconds to keep cached hop count and domain name (default %u). 0 = no expiration\n --ipcache-hostname=[0|1]\t\t\t\t; 1 or no argument enables ip->hostname caching\n --reasm-disable=[type[,type]]\t\t\t\t; disable reasm for these L7 payloads : tls_client_hello quic_initial . if no argument - disable all reasm.\n\nWINDIVERT FILTER:\n --wf-iface=<int>[.<int>]\t\t\t\t; numeric network interface and subinterface indexes\n --wf-l3=ipv4|ipv6\t\t\t\t\t; L3 protocol filter. multiple comma separated values allowed.\n --wf-tcp-in=[~]port1[-port2]\t\t\t\t; TCP in port filter. ~ means negation. multiple comma separated values allowed.\n --wf-tcp-out=[~]port1[-port2]\t\t\t\t; TCP out port filter. ~ means negation. multiple comma separated values allowed.\n --wf-udp-in=[~]port1[-port2]\t\t\t\t; UDP in port filter. ~ means negation. multiple comma separated values allowed.\n --wf-udp-out=[~]port1[-port2]\t\t\t\t; UDP out port filter. ~ means negation. multiple comma separated values allowed.\n --wf-tcp-empty=[0|1]\t\t\t\t\t; enable processing of empty tcp packets without flags SYN,RST,FIN (default : 0)\n --wf-icmp-in=type[:code]\t\t\t\t; ICMP out filter. multiple comma separated values allowed.\n --wf-icmp-out=type[:code]\t\t\t\t; ICMP in filter. multiple comma separated values allowed.\n --wf-ipp-in=proto\t\t\t\t\t; IP protocol in filter. multiple comma separated values allowed.\n --wf-ipp-out=proto\t\t\t\t\t; IP protocol out filter. multiple comma separated values allowed.\n --wf-raw-part=<filter>|@<filename>\t\t\t; partial raw windivert filter combined by OR. multiple allowed\n --wf-raw-filter=<filter>|@<filename>\t\t\t; partial raw windivert filter combined by AND. only one allowed\n --wf-filter-lan=0|1\t\t\t\t\t; add excluding filter for non-global IP (default : 1)\n --wf-filter-loopback=0|1\t\t\t\t; add excluding filter for loopback (default : 1)\n --wf-raw=<filter>|@<filename>\t\t\t\t; full raw windivert filter string or filename. replaces --wf-tcp,--wf-udp,--wf-raw-part\n --wf-dup-check=0|1\t\t\t\t\t; 1 (default) = do not allow duplicate winws2 instances with the same wf filter\n --wf-save=<filename>\t\t\t\t\t; save windivert filter string to a file and exit\n\nLOGICAL NETWORK FILTER:\n --ssid-filter=ssid1[,ssid2,ssid3,...]\t\t\t; enable winws2 only if any of specified wifi SSIDs connected\n --ssid-filter-neg=[0|1]\t\t\t\t; invert SSID filter\n --nlm-filter=net1[,net2,net3,...]\t\t\t; enable winws2 only if any of specified NLM network is connected. names and GUIDs are accepted.\n --nlm-filter-neg=[0|1]\t\t\t\t\t; invert NLM filter\n --nlm-list[=all]\t\t\t\t\t; list Network List Manager (NLM) networks. connected only or all.\n\nDESYNC ENGINE INIT:\n --writable[=<dir_name>]\t\t\t\t; create writable dir for LUA scripts and pass it in WRITABLE env variable (only one dir possible)\n --blob=<item_name>:[+ofs]@<filename>|0xHEX\t\t; load blob to LUA var <item_name>\n --lua-init=@<filename>|<lua_text>\t\t\t; load LUA program from a file or string. if multiple parameters present order of execution is preserved. gzipped files are supported.\n --lua-gc=<int>\t\t\t\t\t\t; forced garbage collection every N sec. default %u sec. triggers only when a packet arrives. 0 = disable.\n\nMULTI-STRATEGY:\n --new[=<name>]\t\t\t\t\t\t; begin new profile. optionally set name\n --skip\t\t\t\t\t\t\t; do not use this profile\n --name=<name>\t\t\t\t\t\t; set profile name\n --template[=<name>]\t\t\t\t\t; use this profile as template (must be named or will be useless)\n --cookie[=<string>]\t\t\t\t\t; pass this profile-bound string to LUA\n --import=<name>\t\t\t\t\t; populate current profile with template data\n --filter-l3=ipv4|ipv6\t\t\t\t\t; L3 protocol filter. multiple comma separated values allowed.\n --filter-tcp=[~]port1[-port2]|*\t\t\t; TCP port filter. ~ means negation. setting tcp filter and not setting others denies others. comma separated list allowed.\n --filter-udp=[~]port1[-port2]|*\t\t\t; UDP port filter. ~ means negation. setting udp filter and not setting others denies others. comma separated list allowed.\n --filter-icmp=type[:code]|*\t\t\t\t; ICMP type+code filter. setting icmp filter and not setting others denies others. comma separated list allowed.\n --filter-ipp=proto\t\t\t\t\t; IP protocol filter. setting up ipp filter and not setting others denies others. comma separated list allowed.\n --filter-l7=proto[,proto]\t\t\t\t; L6-L7 protocol filter : %s\n --ipset=<filename>\t\t\t\t\t; ipset include filter (one ip/CIDR per line, ipv4 and ipv6 accepted, gzip supported, multiple ipsets allowed)\n --ipset-ip=<ip_list>\t\t\t\t\t; comma separated fixed subnet list\n --ipset-exclude=<filename>\t\t\t\t; ipset exclude filter (one ip/CIDR per line, ipv4 and ipv6 accepted, gzip supported, multiple ipsets allowed)\n --ipset-exclude-ip=<ip_list>\t\t\t\t; comma separated fixed subnet list\n --hostlist=<filename>\t\t\t\t\t; apply dpi desync only to the listed hosts (one host per line, subdomains auto apply, gzip supported, multiple hostlists allowed)\n --hostlist-domains=<domain_list>\t\t\t; comma separated fixed domain list\n --hostlist-exclude=<filename>\t\t\t\t; do not apply dpi desync to the listed hosts (one host per line, subdomains auto apply, gzip supported, multiple hostlists allowed)\n --hostlist-exclude-domains=<domain_list>\t\t; comma separated fixed domain list\n --hostlist-auto=<filename>\t\t\t\t; detect DPI blocks and build hostlist automatically\n --hostlist-auto-fail-threshold=<int>\t\t\t; how many failed attempts cause hostname to be added to auto hostlist (default : %d)\n --hostlist-auto-fail-time=<int>\t\t\t; all failed attemps must be within these seconds (default : %d)\n --hostlist-auto-retrans-threshold=<int>\t\t; how many request retransmissions cause attempt to fail (default : %d)\n --hostlist-auto-retrans-maxseq=<int>\t\t\t; count retransmissions only within this relative sequence (default : %u)\n --hostlist-auto-retrans-reset=[0|1]\t\t\t; send RST to retransmitter to break long wait (default: 1)\n --hostlist-auto-incoming-maxseq=<int>\t\t\t; treat tcp connection as successful if incoming relative sequence exceedes this threshold (default : %u)\n --hostlist-auto-udp-out=<int>\t\t\t\t; udp failure condition : sent at least `udp_out` packets (default : %u)\n --hostlist-auto-udp-in=<int>\t\t\t\t; udp failure condition : received not more than `udp_in` packets (default : %u)\n --hostlist-auto-debug=<logfile>\t\t\t; debug auto hostlist positives (global parameter)\n\nLUA PACKET PASS MODE:\n --payload=type[,type]\t\t\t\t\t; set payload types following LUA functions should process : %s\n --out-range=<mode>[<int>][(-|<)<mode>[<int>]]\t\t; set outgoing packet range for following LUA functions. '-' - include end pos, '<' - not include. mode meaning : n - packet number, d - data packet number, s - relative sequence, p - data position relative sequence, b - byte count, x - never, a - always\n --in-range=<mode>[<int>][(-|<)<mode>[<int>]]\t\t; set incoming packet range for following LUA functions. '-' - include end pos, '<' - not include. mode meaning : n - packet number, d - data packet number, s - relative sequence, p - data position relative sequence, b - byte count, x - never, a - always\n\nLUA DESYNC ACTION:\n --lua-desync=<functon>[:param1=val1[:param2=val2]]\t; call LUA function when packet received\n";
